      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Which GST office handles healthcare in Delhi?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "5 zones: Central, North, South, East, West. Saket = South, Rohini = North. Patron files healthcare-specific returns for all 5 zones from Rohini office."
          }
        },
        {
          "@type": "Question",
          "name": "Are healthcare services exempt from GST?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Core clinical services exempt (Notification 12/2017, SAC 9993). Room rent >Rs 5,000/day: 5%. Cosmetic: 18%. Standalone diagnostics: 18%. Pharmacy counter: 5-12%. Correct segregation mandatory."
          }
        },
        {
          "@type": "Question",
          "name": "Can hospitals claim ITC?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Only on inputs for taxable supplies (room rent >Rs 5,000, cosmetic, pharmacy). Must reverse ITC proportionally for exempt supplies (S.17(2)). Monthly apportionment mandatory."
          }
        },
        {
          "@type": "Question",
          "name": "What is the fee for healthcare accounting?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Clinic from Rs 8,000/month. Diagnostics/pharmacy Rs 12,000-20,000. Hospital (50-200 beds) Rs 20,000-40,000. Multi-specialty Rs 50,000+. Includes GST segregation, TDS, payroll."
          }
        },
        {
          "@type": "Question",
          "name": "Do doctors need Section 44ADA?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Doctors with gross receipts ≤Rs 75L (95% digital) can opt for S.44ADA presumptive (50% of receipts = income). Above threshold: full books + possibly S.44AB tax audit."
          }
        },
        {
          "@type": "Question",
          "name": "Do standalone diagnostics need GST?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes if turnover >Rs 20L. Standalone diagnostic services attract 18% GST. Diagnostics within hospital admission are exempt. Classification critical."
          }
        },
        {
          "@type": "Question",
          "name": "What about doctor TDS (S.194J)?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "10% TDS on visiting consultant fees. Monthly deduction, quarterly filing on TRACES. If not deducted: 30% disallowance of expense under S.40(a)(ia)."
          }
        },
        {
          "@type": "Question",
          "name": "How fast is onboarding?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "48 hours. Month 1: revenue classification, GST mapping, data migration. Full monthly reporting with exempt/taxable segregation from Month 2. Quick Answers Hospital mein GST lagta hai kya? Clinical services exempt hain. Room rent Rs 5,000/day se zyada par 5% GST. Cosmetic surgery par 18%. Doctor ko ITR file karna zaroori hai? Haan. Rs 75L tak S.44ADA se. Usse zyada hone par full books + tax audit. Healthcare accounting ka kharcha? Clinic Rs 8,000/month se. Hospital Rs 20,000+ size ke hisaab se."
          }
        }
      ]
    }
